function timeline(items) {
  return items
    .map(
      ([date, title, place, body]) =>
        `<article class="timeline-item"><p class="date">${date}</p><div><h3>${title} <span>· ${place}</span></h3>${(Array.isArray(body) ? body : [body]).map((paragraph) => `<p>${paragraph}</p>`).join('')}</div></article>`,
    )
    .join('');
}
function render() {
  const t = cv[lang];
  document.documentElement.lang = lang;
  document.title = `Lovro Zezelj — ${lang === 'en' ? 'Full-stack developer' : 'Full-Stack-Entwickler'}`;
  document.querySelectorAll('[data-i18n]').forEach((el) => (el.textContent = t[el.dataset.i18n]));
  document.getElementById('language-switch').textContent = lang === 'en' ? 'DE' : 'EN';
  document.getElementById('project-grid').innerHTML = projects
    .map(
      ([name, url, tags, sourceUrl], i) =>
        `<article class="project"><p class="project-kicker">${t.projectCopy[i][1]}</p><h3>${name}</h3><p>${t.projectCopy[i][0]}</p><ul class="project-details">${t.projectDetails[i].map((detail) => `<li>${detail}</li>`).join('')}</ul><div class="tags">${tags.map((x) => `<span class="tag">${x}</span>`).join('')}</div><a class="project-link" href="${url}" target="_blank" rel="noreferrer">${t.visitProject} ↗</a><a class="project-source" href="${sourceUrl}" target="_blank" rel="noreferrer">${t.sourceCode} ↗</a><a class="demo-request" href="mailto:lovro.zezelj@gmail.com?subject=${encodeURIComponent(`${t.requestDemo}: ${name}`)}">${t.requestDemo} →</a></article>`,
    )
    .join('');
  document.getElementById('experience-list').innerHTML = timeline(t.experience);
  document.getElementById('education-list').innerHTML = timeline(t.education);
  document.getElementById('skills-list').innerHTML = t.skills
    .map(
      ([title, body]) => `<article class="skill-group"><h3>${title}</h3><p>${body}</p></article>`,
    )
    .join('');
  localStorage.setItem('cv-language', lang);
}
document.getElementById('language-switch').addEventListener('click', () => {
  lang = lang === 'en' ? 'de' : 'en';
  render();
});
const cvDropdown = document.getElementById('cv-dropdown');
const cvToggle = document.getElementById('download-cv');
const cvOptions = document.getElementById('cv-language-options');

function closeCvDropdown() {
  cvOptions.hidden = true;
  cvToggle.setAttribute('aria-expanded', 'false');
}

cvToggle.addEventListener('click', () => {
  cvOptions.hidden = !cvOptions.hidden;
  cvToggle.setAttribute('aria-expanded', String(!cvOptions.hidden));
});

document.addEventListener('click', (event) => {
  if (!cvDropdown.contains(event.target)) closeCvDropdown();
});

cvDropdown.addEventListener('keydown', (event) => {
  if (event.key === 'Escape') {
    closeCvDropdown();
    cvToggle.focus();
  }
  if (event.key === 'ArrowDown' && event.target === cvToggle) {
    event.preventDefault();
    cvOptions.hidden = false;
    cvToggle.setAttribute('aria-expanded', 'true');
    cvOptions.querySelector('button').focus();
  }
});

cvOptions.querySelectorAll('button').forEach((option) => {
  option.addEventListener('click', () => {
    closeCvDropdown();
    cvToggle.focus();
    const websiteLanguage = lang;
    lang = option.dataset.cvLanguage;
    render();
    updateLanguageButton();

    const restoreLanguage = () => {
      lang = websiteLanguage;
      render();
      updateLanguageButton();
      window.removeEventListener('afterprint', restoreLanguage);
    };
    window.addEventListener('afterprint', restoreLanguage);
    // Allow the selected language and closed dropdown to paint before printing.
    requestAnimationFrame(() => {
      requestAnimationFrame(() => {
        try {
          window.print();
        } catch (error) {
          restoreLanguage();
          throw error;
        }
      });
    });
  });
});
document.getElementById('year').textContent = new Date().getFullYear();
render();
function updateLanguageButton() {
  const button = document.getElementById('language-switch');
  button.textContent = lang.toUpperCase();
  button.setAttribute(
    'aria-label',
    lang === 'en'
      ? 'English selected; switch to German'
      : 'Deutsch ausgewählt; zu Englisch wechseln',
  );
  button.title = button.getAttribute('aria-label');
}
document.getElementById('language-switch').addEventListener('click', updateLanguageButton);
updateLanguageButton();

