document
  .querySelectorAll('.cv-contact > *, .contact-links a, .email-link, .contact-birthday')
  .forEach((element) => {
    const href = element.getAttribute('href') || '';
    const type = href.startsWith('mailto:')
      ? 'email'
      : href.includes('github.com')
        ? 'github'
        : href.includes('linkedin.com')
          ? 'linkedin'
          : href
            ? 'website'
            : 'location';
    const icon = document.createElementNS('http://www.w3.org/2000/svg', 'svg');
    icon.setAttribute('viewBox', '0 0 24 24');
    icon.setAttribute('class', 'contact-icon');
    icon.setAttribute('aria-hidden', 'true');
    icon.setAttribute('focusable', 'false');
    const path = document.createElementNS('http://www.w3.org/2000/svg', 'path');
    path.setAttribute('d', contactIconPaths[element.dataset.contactIcon || type]);
    icon.append(path);
    element.prepend(icon);
  });
